import csv, re
from datetime import date
from collections import OrderedDict

MONTHS={m:i+1 for i,m in enumerate(['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'])}

def parse_date(s):
    s=s.strip()
    m=re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})',s)
    if m: return date(int(m[1]),int(m[2]),int(m[3]))
    m=re.fullmatch(r'(\d{1,2})/(\d{1,2})/(\d{4})',s)
    if m: return date(int(m[3]),int(m[1]),int(m[2]))
    m=re.fullmatch(r'(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})',s)
    if m: return date(int(m[3]),MONTHS[m[2][:3].lower()],int(m[1]))
    raise ValueError(s)

def parse_amt(s):
    s=s.strip().replace('USD','').replace('$','').replace(',','').strip()
    return int(round(float(s)*100))

CAT={'taxi':'Travel','uber':'Travel','flight':'Travel',
     'hotel':'Lodging','airbnb':'Lodging',
     'lunch':'Meals','dinner':'Meals','coffee':'Meals',
     'saas':'Software','software':'Software','license':'Software',
     'books':'Learning','course':'Learning'}

rows=list(csv.DictReader(open('expenses.csv')))
seen={}
order=[]
for r in rows:
    rid=r['id'].strip()
    if rid in seen: continue
    seen[rid]=r; order.append(rid)

cats={}
flags=[]
for rid in order:
    r=seen[rid]
    st=r['status'].strip().lower()
    if st=='void': continue
    d=parse_date(r['date'])
    if d.year!=2026 or d.month!=10: continue
    c=CAT[r['category'].strip().lower()]
    a=parse_amt(r['amount'])
    cats.setdefault(c,[0,0])
    cats[c][0]+=1; cats[c][1]+=a
    if a>50000: flags.append((int(rid),a))

total=sum(v[1] for v in cats.values())
print('count',sum(v[0] for v in cats.values()),'total',total)
for c,v in sorted(cats.items(), key=lambda kv:-kv[1][1]):
    print(c,v[0],v[1])
flags.sort()
print('flags',flags)
EOF", "description": "Compute October totals from CSV"}

