import csv, re
from datetime import date
MONTHS={m:i+1 for i,m in enumerate(['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'])}
def pd(s):
    s=s.strip()
    for pat,f in [(r'(\d{4})-(\d{2})-(\d{2})',lambda m:(int(m[1]),int(m[2]),int(m[3]))),
                  (r'(\d{1,2})/(\d{1,2})/(\d{4})',lambda m:(int(m[3]),int(m[1]),int(m[2]))),
                  (r'(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})',lambda m:(int(m[3]),MONTHS[m[2][:3].lower()],int(m[1])))]:
        m=re.fullmatch(pat,s)
        if m:
            y,mo,d=f(m); return date(y,mo,d)
    raise ValueError(s)
def pa(s):
    s=s.strip().replace('USD','').replace('$','').replace(',','').strip()
    return int(round(float(s)*100))
CAT={'taxi':'Travel','uber':'Travel','flight':'Travel','hotel':'Lodging','airbnb':'Lodging','lunch':'Meals','dinner':'Meals','coffee':'Meals','saas':'Software','software':'Software','license':'Software','books':'Learning','course':'Learning'}
rows=list(csv.DictReader(open('expenses.csv')))
seen={}
for r in rows: seen.setdefault(r['id'].strip(),r)
cats={}; flags=[]
for rid,r in seen.items():
    if r['status'].strip().lower()=='void': continue
    d=pd(r['date'])
    if (d.year,d.month)!=(2026,10): continue
    c=CAT[r['category'].strip().lower()]; a=pa(r['amount'])
    n,tot=cats.get(c,(0,0)); cats[c]=(n+1,tot+a)
    if a>50000: flags.append((int(rid),a))
total=sum(t for _,t in cats.values())
def money(c): return '${:,.2f}'.format(c/100)
out=['# Expense Report — October 2026', f'Total: {money(total)}', '',
     '| Category | Items | Amount |','|---|---:|---:|']
for c,(n,t) in sorted(cats.items(), key=lambda kv:(-kv[1][1], kv[0])):
    out.append(f'| {c} | {n} | {money(t)} |')
out+=['','## Flags']
if flags:
    for rid,a in sorted(flags): out.append(f'- #{rid} {money(a)} — over $500, receipt required')
else: out.append('- none')
open('report.md','w').write('\n'.join(out)+'\n')
print('\n'.join(out))
# verification
assert sum(t for _,t in cats.values())==total
print('sum check OK', total)
EOF", "description": "Generate report.md and verify total"}

