import csv,re
from datetime import date
from collections import Counter
MONTHS={m:i+1 for i,m in enumerate(['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'])}
def pd(s):
    s=s.strip()
    for pat,f in [(r'(\d{4})-(\d{2})-(\d{2})',lambda m:(int(m[1]),int(m[2]),int(m[3]))),
                  (r'(\d{1,2})/(\d{1,2})/(\d{4})',lambda m:(int(m[3]),int(m[1]),int(m[2]))),
                  (r'(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})',lambda m:(int(m[3]),MONTHS[m[2][:3].lower()],int(m[1])))]:
        m=re.fullmatch(pat,s)
        if m:
            y,mo,d=f(m); return date(y,mo,d)
    raise ValueError(repr(s))
rows=list(csv.DictReader(open('expenses.csv')))
seen={}
for r in rows: seen.setdefault(r['id'].strip(),r)
print('unique',len(seen))
for k,r in seen.items(): print(k,r['date'],pd(r['date']),r['status'],r['amount'])
print(Counter((pd(r['date']).year,pd(r['date']).month,r['status']) for r in seen.values()))
